
from pathlib import Path
import json

# START: Variables

# Folder containing this Python script.
gif_root = Path(__file__).parent

# JavaScript file generated by this script.
output_file = gif_root / "celebration_gif_manifest.js"

# Supported animated image extensions.
gif_extensions = {".gif"}

# STOP: Variables


# START: Build GIF manifest

celebration_gif_packs = {}

# Find each pack folder, such as 1, 2 and 3.
for pack_folder in sorted(gif_root.iterdir()):

    if not pack_folder.is_dir():
        continue

    if pack_folder.name.startswith("."):
        continue

    # Find GIF files inside this pack.
    gif_files = sorted(
        file
        for file in pack_folder.iterdir()
        if file.is_file()
        and file.suffix.lower() in gif_extensions
    )

    # Store paths relative to the website's main folder.
    if gif_files:
        celebration_gif_packs[pack_folder.name] = [
            f"images/celebration-gifs/{pack_folder.name}/{file.name}"
            for file in gif_files
        ]

# STOP: Build GIF manifest


# START: Generate JavaScript file

javascript_content = (
    "/* Automatically generated by generate_gif_manifest.py */\n"
    "/* Run the Python script to refresh this file. */\n\n"
    "window.celebration_gif_packs = "
    + json.dumps(celebration_gif_packs, indent=4)
    + ";\n"
)

output_file.write_text(javascript_content, encoding="utf-8")

# STOP: Generate JavaScript file


# START: Report results

print(f"Generated: {output_file.name}")
print()

for pack_name, gif_files in celebration_gif_packs.items():
    print(f"Pack {pack_name}: {len(gif_files)} GIF(s)")

print()
print(f"Total GIFs: {sum(len(files) for files in celebration_gif_packs.values())}")

# STOP: Report results
